let currentLanguage='pt-BR';let currentTheme='light';
try{currentLanguage=['pt-BR','en','es'].includes(localStorage.getItem('sp-language'))?localStorage.getItem('sp-language'):'pt-BR';const saved=localStorage.getItem('sp-theme');currentTheme=saved==='dark'||saved==='light'?saved:(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light')}catch{}
function translate(value,language=currentLanguage){const dictionary=language==='en'?english:language==='es'?spanish:null;return dictionary&&Object.hasOwn(dictionary,value)?dictionary[value]:value}
function t(value){return translate(value)}
const staticNodes=[...document.querySelectorAll('.brand span,nav a,.intro .eyebrow,h1,.lede,.intro .button,.image-label,.stamp,.section-head .eyebrow,.section-head h2,.section-head>p,[data-filter],.note,.postal .eyebrow,.postal h2,.postal>div:first-child>p:not(#status),label[for="message"],.post-preview em,.about .eyebrow,.about h2,.about>p:last-child,summary,.config>p:not([role="status"]),#save-config,footer p,footer>a:last-child')].map(el=>({el,original:el.innerHTML}));
function applyStaticLanguage(){
 document.documentElement.lang=currentLanguage;document.title=t('São Paulo em Camadas');
 staticNodes.forEach(({el,original})=>{if(el.matches('nav a[href="#postal"]'))el.innerHTML=`${t('Meu cartão')} <span id="count">0/3</span>`;else el.innerHTML=t(original)});
 document.querySelector('.close').setAttribute('aria-label',t('Fechar história'));document.querySelector('.filters').setAttribute('aria-label',t('Filtrar histórias'));document.querySelector('.hero-art img').alt=t('Vista urbana de São Paulo');
 document.querySelector('.coordinates').innerHTML=`23°33′ S &nbsp; 46°38′ O &nbsp; · &nbsp; ${t('BRASIL')}`;
 
 document.querySelector('#language-label').textContent=t('Idioma');document.querySelector('#theme-label').textContent=t('Aparência');
 document.querySelector('#theme-light').textContent=t('Claro');document.querySelector('#theme-dark').textContent=t('Escuro');
 document.querySelector('#language').value=currentLanguage;document.querySelector('#theme').value=currentTheme;
}
const preferenceBar=document.createElement('div');preferenceBar.className='preferences';preferenceBar.innerHTML='<label><span id="language-label">Idioma</span><select id="language"><option value="pt-BR" lang="pt-BR">Português (Brasil)</option><option value="en" lang="en">English</option><option value="es" lang="es">Español</option></select></label><label><span id="theme-label">Aparência</span><select id="theme"><option id="theme-light" value="light">Claro</option><option id="theme-dark" value="dark">Escuro</option></select></label>';document.querySelector('header').append(preferenceBar);
if(initialSharedTrip)currentLanguage=initialSharedTrip.lang;
function applyTheme(){document.documentElement.dataset.theme=currentTheme;document.querySelector('#theme').value=currentTheme}
applyStaticLanguage();applyTheme();document.querySelector('#message').value=t('Tem um mundo inteiro aqui.');document.querySelector('#preview-message').textContent=document.querySelector('#message').value;
document.querySelector('#theme').onchange=e=>{currentTheme=e.target.value;applyTheme();try{localStorage.setItem('sp-theme',currentTheme)}catch{}};
document.querySelector('#language').onchange=e=>{
 const message=document.querySelector('#message'),oldDefault=t('Tem um mundo inteiro aqui.');currentLanguage=e.target.value;
 if(message.value===oldDefault)message.value=t('Tem um mundo inteiro aqui.');
 applyStaticLanguage();document.querySelector('#preview-message').textContent=message.value;
 document.querySelector('#status').textContent='';
 if(document.querySelector('#story').open)document.querySelector('#story').close();
 render();refreshLocalizedFields();try{localStorage.setItem('sp-language',currentLanguage)}catch{}
};
